import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom fused ConvTranspose3d + BatchNorm3d kernel
conv_bn_fusion_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_conv_bn_kernel(
    const float* input, const float* weight, const float* bias,
    const float* bn_weight, const float* bn_bias, float* output,
    int B, int Cin, int Cout, int D, int H, int W,
    int K, int S, int P, int D_out, int H_out, int W_out
) {
    int n = blockIdx.x * blockDim.x + threadIdx.x;
    int c = blockIdx.y * blockDim.y + threadIdx.y;
    int d = blockIdx.z * blockDim.z + threadIdx.z;

    if (n >= B || c >= Cout || d >= D_out) return;

    float sum = 0.0f;
    for (int cin = 0; cin < Cin; ++cin) {
        for (int kd = 0; kd < K; ++kd) {
            for (int kh = 0; kh < K; ++kh) {
                for (int kw = 0; kw < K; ++kw++) {
                    int input_d = (d*S - P) + kd;
                    int input_h = (blockIdx.z * S - P) + kh;
                    int input_w = threadIdx.x * S - P + kw;

                    if (input_d >= 0 && input_d < D &&
                        input_h >= 0 && input_h < H &&
                        input_w >= 0 && input_w < W) {
                        int input_idx = n * Cin*D*H*W + cin*D*H*W + input_d*H*W + input_h*W + input_w;
                        int weight_idx = c * Cin*K*K*K + cin*K*K*K + kd*K*K + kh*K + kw;
                        sum += input[input_idx] * weight[weight_idx];
                    }
                }
            }
        }
    }

    sum += bias[c];
    sum = bn_weight[c] * sum + bn_bias[c];
    output[n*Cout*D_out*H_out*W_out + c*D_out*H_out*W_out + d*H_out*W_out + blockIdx.z*W_out + threadIdx.x] = sum;
}

torch::Tensor fused_conv_bn_cuda(
    torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
    torch::Tensor bn_weight, torch::Tensor bn_bias,
    int S, int P, int D_out, int H_out, int W_out
) {
    auto B = input.size(0);
    auto Cin = input.size(1);
    auto D = input.size(2);
    auto H = input.size(3);
    auto W = input.size(4);
    auto Cout = weight.size(0);
    auto K = weight.size(2);

    auto output = torch::zeros({B, Cout, D_out, H_out, W_out}, input.options());

    dim3 threads(32, 4);
    dim3 blocks(
        (B + threads.x - 1) / threads.x,
        (Cout + threads.y - 1) / threads.y,
        (D_out + threads.z - 1) / threads.z
    );

    fused_conv_bn_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        bn_weight.data_ptr<float>(),
        bn_bias.data_ptr<float>(),
        output.data_ptr<float>(),
        B, Cin, Cout, D, H, W,
        K, S, P, D_out, H_out, W_out
    );

    return output;
}
"""

# Custom fused average pooling kernel
fused_pool_source = """
#include <torch/extension.h>
#include <cuda.h>

__global__ void fused_pool_kernel(const float* input, float* output, 
                                 int B, int C, int D, int H, int W) {
    int n = blockIdx.x;
    int c = blockIdx.y;
    int d = threadIdx.x * 2;
    int h = blockIdx.z * 2;
    int w = threadIdx.y * 2;

    if (d >= D || h >= H || w >= W) return;

    float sum = 0.0f;
    for (int dd = 0; dd < 2; ++dd) {
        for (int dh = 0; dh < 2; ++dh) {
            for (int dw = 0; dw < 2; ++dw) {
                sum += input[n*C*D*H*W + c*D*H*W + 
                            (d+dd)*H*W + (h+dh)*W + (w+dw)];
            }
        }
    }
    output[n*C*(D/2)*(H/2)*(W/2) + c*(D/2)*(H/2)*(W/2) + 
          (d/2)*(H/2)*(W/2) + (h/2)*(W/2) + (w/2)] = sum / 8.0f;
}

torch::Tensor fused_pool_cuda(torch::Tensor input) {
    auto B = input.size(0);
    auto C = input.size(1);
    auto D = input.size(2);
    auto H = input.size(3);
    auto W = input.size(4);

    auto output = torch::zeros({B, C, D/2, H/2, W/2}, input.options());

    dim3 threads(16, 16);
    dim3 blocks(B, C, H/2);

    fused_pool_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        B, C, D, H, W
    );

    return output;
}
"""

# Load custom CUDA modules
conv_bn_fusion = load_inline(
    name='conv_bn_fusion',
    cpp_sources='torch::Tensor fused_conv_bn_cuda(torch::Tensor, torch::Tensor, torch::Tensor, torch::Tensor, torch::Tensor, int, int, int, int, int);',
    cuda_sources=conv_bn_fusion_source,
    functions=['fused_conv_bn_cuda'],
    verbose=True
)

fused_pool = load_inline(
    name='fused_pool',
    cpp_sources='torch::Tensor fused_pool_cuda(torch::Tensor);',
    cuda_sources=fused_pool_source,
    functions=['fused_pool_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, bias_shape):
        super(ModelNew, self).__init__()
        self.conv_weight = nn.Parameter(torch.Tensor(
            out_channels, in_channels, kernel_size, kernel_size, kernel_size))
        self.conv_bias = nn.Parameter(torch.Tensor(out_channels))
        self.bn_weight = nn.Parameter(torch.Tensor(out_channels))
        self.bn_bias = nn.Parameter(torch.Tensor(out_channels))

        nn.init.kaiming_normal_(self.conv_weight)
        self.conv_bias.data.zero_()
        self.bn_weight.data.fill_(1.0)
        self.bn_bias.data.zero_()

        self.stride = stride
        self.padding = padding

    def forward(self, x):
        _, _, D, H, W = x.shape
        D_out = (D - 1) * self.stride - 2*self.padding + 3
        H_out = (H - 1) * self.stride - 2*self.padding + 3
        W_out = (W - 1) * self.stride - 2*self.padding + 3

        x = conv_bn_fusion.fused_conv_bn_cuda(
            x, self.conv_weight, self.conv_bias,
            self.bn_weight, self.bn_bias,
            self.stride, self.padding, D_out, H_out, W_out
        )

        x = fused_pool.fused_pool_cuda(x)
        x = fused_pool.fused_pool_cuda(x)
        return x
